package org.eclipse.kura.container.orchestration.provider;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

import org.eclipse.kura.container.orchestration.provider.impl.ContainerOrchestrationServiceImpl;
import org.junit.Test;
import org.mockito.Mockito;

import com.github.dockerjava.api.DockerClient;
import com.github.dockerjava.api.exception.NotFoundException;
import com.github.dockerjava.api.model.Container;
import com.github.dockerjava.api.model.ContainerPort;
import com.github.dockerjava.api.model.Image;

public class ContainerImageDigestsTest {

    private static final String CONTAINER_ID = "1d3dewf34r5";
    private static final String IMAGE_ID = "sha256:2d2fb2cabc8fa6b894bd7d82158dd7a9dd5815d240f75a93db0853a008a0cf2b";
    private static final String DIGEST = "sha256:c26ae7472d624ba1fafd296e73cecc4f93f853088e6a9c13c0d52f6ca5865107";
    private static final String ALLOWED_IMAGE_NAME = "nginx";
    private static final String OTHER_DIGEST = "sha256:f9d633ff6640178c2d0525017174a688e2c1aef28f0a0130b26bd5554491f0da";

    private final DockerClient dockerClient = mock(DockerClient.class, Mockito.RETURNS_DEEP_STUBS);
    private final ContainerOrchestrationServiceImpl service = new ContainerOrchestrationServiceImpl();
    private Set<String> imageDigests;

    @Test
    public void digestsAreThoseOfTheImageTheContainerRuns() {
        givenServiceConnectedToDocker();
        givenContainerRunningImage(CONTAINER_ID, IMAGE_ID);
        givenImageWithRepoDigests(IMAGE_ID, "nginx@" + DIGEST, "registry.local/nginx@" + OTHER_DIGEST);

        whenImageDigestsAreRequestedFor(CONTAINER_ID);

        thenImageDigestsAre(DIGEST, OTHER_DIGEST);
    }

    @Test
    public void containerNamedDifferentlyFromItsImageHasItsImageDigests() {
        givenServiceConnectedToDocker();
        givenContainerNamed(CONTAINER_ID, "my-app");
        givenContainerRunningImage(CONTAINER_ID, IMAGE_ID);
        givenImageWithRepoDigests(IMAGE_ID, ALLOWED_IMAGE_NAME + "@" + DIGEST);
        givenNoLocalImageNamed("my-app");

        whenImageDigestsAreRequestedFor(CONTAINER_ID);

        thenImageDigestsAre(DIGEST);
    }

    @Test
    public void containerNamedLikeAnotherImageDoesNotGetThatImageDigests() {
        givenServiceConnectedToDocker();
        givenContainerNamed(CONTAINER_ID, ALLOWED_IMAGE_NAME);
        givenContainerRunningImage(CONTAINER_ID, IMAGE_ID);
        givenImageWithRepoDigests(IMAGE_ID, "other@" + OTHER_DIGEST);
        givenLocalImageNamed(ALLOWED_IMAGE_NAME, ALLOWED_IMAGE_NAME + "@" + DIGEST);

        whenImageDigestsAreRequestedFor(CONTAINER_ID);

        thenImageDigestsAre(OTHER_DIGEST);
    }

    @Test
    public void unknownContainerHasNoDigests() {
        givenServiceConnectedToDocker();
        givenNoContainerWithId(CONTAINER_ID);

        whenImageDigestsAreRequestedFor(CONTAINER_ID);

        thenImageDigestsAre();
    }

    private void givenServiceConnectedToDocker() {
        this.service.setDockerClient(this.dockerClient);
    }

    private void givenContainerNamed(String containerId, String containerName) {
        Container container = mock(Container.class);
        when(container.getId()).thenReturn(containerId);
        when(container.getNames()).thenReturn(new String[] { "/" + containerName });
        when(container.getImage()).thenReturn("image:latest");
        when(container.getPorts()).thenReturn(new ContainerPort[0]);
        when(container.getState()).thenReturn("running");
        when(this.dockerClient.listContainersCmd().withShowAll(true).exec())
                .thenReturn(Collections.singletonList(container));
    }

    private void givenNoLocalImageNamed(String imageName) {
        when(this.dockerClient.listImagesCmd().withImageNameFilter(imageName).exec())
                .thenReturn(Collections.emptyList());
    }

    private void givenLocalImageNamed(String imageName, String... repoDigests) {
        Image image = mock(Image.class);
        when(image.getRepoDigests()).thenReturn(repoDigests);
        when(this.dockerClient.listImagesCmd().withImageNameFilter(imageName).exec())
                .thenReturn(Collections.singletonList(image));
    }

    private void givenContainerRunningImage(String containerId, String imageId) {
        when(this.dockerClient.inspectContainerCmd(containerId).exec().getImageId()).thenReturn(imageId);
    }

    private void givenImageWithRepoDigests(String imageId, String... repoDigests) {
        when(this.dockerClient.inspectImageCmd(imageId).exec().getRepoDigests()).thenReturn(Arrays.asList(repoDigests));
    }

    private void givenNoContainerWithId(String containerId) {
        when(this.dockerClient.inspectContainerCmd(containerId).exec())
                .thenThrow(new NotFoundException("No such container: " + containerId));
    }

    private void whenImageDigestsAreRequestedFor(String containerId) {
        this.imageDigests = this.service.getImageDigestsByContainerId(containerId);
    }

    private void thenImageDigestsAre(String... expectedDigests) {
        assertEquals(new HashSet<>(Arrays.asList(expectedDigests)), this.imageDigests);
    }
}
